// zbr:selfhost/TypeChecker.zbr:4284
                    var ppt: _zbr_ty_Type_ = _zbr_ty_Type_.unknown_;
// zbr:selfhost/TypeChecker.zbr:4285
                    if ((pp.type_ != null)) {
